use std::collections::{BTreeMap, BTreeSet};
use std::error::Error;

use velnor_gen::{Drift, drift};
use velnor_model::RepoPath;
use velnor_render::{Owner, RELEASE_HEADER, VELNOR_GEN_MARKER, owner_of, seal};

type TestResult = Result<(), Box<dyn Error>>;

const HEADER: &str =
    "# Generated by velnor-gen. Change .velnor/rust-ci.toml and run `velnor-gen generate`.\n";

fn none() -> BTreeSet<RepoPath> {
    BTreeSet::new()
}

fn generated() -> String {
    seal(HEADER, "name: Rust CI\n")
}

#[test]
fn check_reports_each_owned_file_that_generate_would_write_or_remove() -> TestResult {
    let workflow = RepoPath::new(".github/workflows/rust-ci.yml")?;
    let other = RepoPath::new(".github/workflows/ci.yml")?;
    let expected = BTreeMap::from([(workflow.clone(), generated())]);
    let disk = |content: Option<&str>| {
        let mut files = BTreeMap::from([(other.clone(), b"name: CI\n".to_vec())]);
        if let Some(text) = content {
            files.insert(workflow.clone(), text.as_bytes().to_vec());
        }
        files
    };
    let listed = BTreeSet::from([other.clone()]);
    let older = seal(HEADER, "name: Older Rust CI\n");
    assert_eq!(drift(&expected, &disk(Some(&generated())), &listed), vec![]);
    assert_eq!(
        drift(&expected, &disk(Some(&older)), &listed),
        vec![Drift::Changed(workflow.clone())]
    );
    assert_eq!(
        drift(&expected, &disk(None), &listed),
        vec![Drift::Missing(workflow.clone())]
    );
    assert_eq!(
        drift(&BTreeMap::new(), &disk(Some(&generated())), &listed),
        vec![Drift::Stale(workflow.clone())]
    );
    assert_eq!(drift(&BTreeMap::new(), &disk(None), &listed), vec![]);
    Ok(())
}

const ENGINE: &str =
    "# Generated by Velnor Actions 0.1.81; edit .velnor/config.toml and regenerate.\nname: CI\n";

fn path(text: &str) -> Result<RepoPath, Box<dyn Error>> {
    Ok(RepoPath::new(text)?)
}

fn disk(path: &RepoPath, text: &str) -> BTreeMap<RepoPath, Vec<u8>> {
    BTreeMap::from([(path.clone(), text.as_bytes().to_vec())])
}

#[test]
fn a_file_the_other_generator_marked_is_never_overwritten() -> TestResult {
    let workflow = path(".github/workflows/rust-ci.yml")?;
    let expected = BTreeMap::from([(workflow.clone(), generated())]);
    for hand_written in [
        ENGINE,
        "name: Rust CI\n",
        "name: Mine\n# Generated by velnor-gen.\n",
    ] {
        {
            assert_eq!(
                drift(&expected, &disk(&workflow, hand_written), &none()),
                vec![Drift::Foreign(workflow.clone())],
                "{hand_written}"
            );
        }
    }
    Ok(())
}

#[test]
fn a_marked_file_velnor_gen_does_not_write_is_stale_whatever_its_name() -> TestResult {
    let other = path(".github/workflows/release.yml")?;
    {
        assert_eq!(
            drift(&BTreeMap::new(), &disk(&other, &generated()), &none()),
            vec![Drift::Stale(other.clone())]
        );
    }
    Ok(())
}

#[test]
fn the_engines_marked_file_is_left_alone() -> TestResult {
    let other = path(".github/workflows/ci.yml")?;
    {
        assert_eq!(
            drift(&BTreeMap::new(), &disk(&other, ENGINE), &none()),
            vec![]
        );
    }
    Ok(())
}

#[test]
fn an_unmarked_file_is_drift_unless_external_workflows_lists_it() -> TestResult {
    let other = path(".github/workflows/release.yml")?;
    let files = disk(&other, "name: Release\n");
    assert_eq!(
        drift(&BTreeMap::new(), &files, &none()),
        vec![Drift::Unmarked(other.clone())]
    );
    let listed = BTreeSet::from([other.clone()]);
    assert_eq!(drift(&BTreeMap::new(), &files, &listed), vec![]);
    Ok(())
}

#[test]
fn a_forged_header_is_not_a_velnor_gen_file_and_check_reports_it() -> TestResult {
    let workflow = path(".github/workflows/rust-ci.yml")?;
    let expected = BTreeMap::from([(workflow.clone(), generated())]);
    let forged = generated().replace("Rust CI", "Evil");
    {
        assert_eq!(
            drift(&expected, &disk(&workflow, &forged), &none()),
            vec![Drift::Foreign(workflow.clone())]
        );
    }
    for text in [
        "# Generated by velnor-gen.fork\nname: A\n",
        "# Generated by velnor-genie\n",
        "\n# Generated by velnor-gen.\n",
        " # Generated by velnor-gen.\n",
    ] {
        assert_eq!(owner_of(text.as_bytes()), Owner::Nobody, "{text:?}");
    }
    for text in [
        "# Generated by velnor-gen.",
        "# Generated by velnor-gen.\r\nname: A\n",
        "# Generated by velnor-gen. Change x.\n",
        "# Generated by velnor-gen.\n# velnor-gen-sha256: 00\nname: A\n",
    ] {
        assert_eq!(owner_of(text.as_bytes()), Owner::Forged, "{text:?}");
    }
    assert_eq!(owner_of(generated().as_bytes()), Owner::VelnorGen);
    Ok(())
}

#[test]
fn a_copied_marker_on_a_hand_written_workflow_is_refused_never_stale() -> TestResult {
    let custom = path(".github/workflows/custom.yml")?;
    let forged = "# Generated by velnor-gen.\nname: Custom\non: push\n";
    {
        assert_eq!(
            drift(&BTreeMap::new(), &disk(&custom, forged), &none()),
            vec![Drift::Foreign(custom.clone())]
        );
    }
    Ok(())
}

#[test]
fn a_header_without_a_digest_is_forged_whether_or_not_the_path_is_expected() -> TestResult {
    let workflow = path(".github/workflows/rust-ci.yml")?;
    let release = path(".github/workflows/release.yml")?;
    let expected = BTreeMap::from([(workflow.clone(), generated())]);
    for (file, header) in [(&workflow, HEADER), (&release, RELEASE_HEADER)] {
        let copied = format!("{header}name: Mine\n");
        assert_eq!(owner_of(copied.as_bytes()), Owner::Forged, "{copied:?}");
        assert_eq!(
            drift(&BTreeMap::new(), &disk(file, &copied), &none()),
            vec![Drift::Foreign(file.clone())]
        );
    }
    let copied = format!("{HEADER}name: Mine\n");
    assert_eq!(
        drift(&expected, &disk(&workflow, &copied), &none()),
        vec![Drift::Foreign(workflow.clone())]
    );
    Ok(())
}

#[test]
fn a_crlf_checkout_of_a_sealed_file_is_still_owned_and_not_drift() -> TestResult {
    let workflow = path(".github/workflows/rust-ci.yml")?;
    let expected = BTreeMap::from([(workflow.clone(), generated())]);
    let crlf = generated().replace('\n', "\r\n");
    assert_eq!(owner_of(crlf.as_bytes()), Owner::VelnorGen);
    assert_eq!(drift(&expected, &disk(&workflow, &crlf), &none()), vec![]);
    assert_eq!(
        drift(&BTreeMap::new(), &disk(&workflow, &crlf), &none()),
        vec![Drift::Stale(workflow.clone())]
    );
    let tampered = crlf.replace("Rust CI", "Evil");
    assert_eq!(owner_of(tampered.as_bytes()), Owner::Forged);
    Ok(())
}

#[test]
fn every_workflow_velnor_gen_writes_is_sealed_so_check_finds_no_drift() -> TestResult {
    let repo = crate::base_save::pinned("0.1.102", "")?;
    let expected = velnor_gen::expected_files(&repo)?;
    assert!(expected.contains_key(&velnor_render::DELTA_CLEANUP_PATH));
    let on_disk: BTreeMap<RepoPath, Vec<u8>> = expected
        .iter()
        .map(|(file, text)| (file.clone(), text.as_bytes().to_vec()))
        .collect();
    assert_eq!(drift(&expected, &on_disk, &none()), vec![]);
    Ok(())
}

#[test]
fn each_generated_header_names_its_own_config() {
    assert!(HEADER.starts_with(VELNOR_GEN_MARKER));
    assert!(HEADER.lines().next().is_some_and(|first| {
        first.contains(".velnor/rust-ci.toml") && first.contains("velnor-gen generate")
    }));
}
